{
  "datasets": [
    {
      "name": "workforce_kpis",
      "displayName": "Workforce KPIs",
      "queryLines": [
        "WITH mx AS (SELECT MAX(CAST(CAST(ValidDate AS TIMESTAMP) AS DATE)) AS mx FROM ramsay_health.ops.vwah_hoursassignment) SELECT   COUNT(DISTINCT StaffNumber) AS distinct_staff,   ROUND(SUM(CAST(WorkHours AS DOUBLE)), 0) AS total_hours,   ROUND(100.0 * SUM(CASE WHEN FulfillmentStatusName='Filled' THEN 1 ELSE 0 END) / COUNT(1), 1) AS fill_rate,   SUM(CASE WHEN FulfillmentStatusName='Unfilled Shift' AND CAST(CAST(ValidDate AS TIMESTAMP) AS DATE) >= date_sub((SELECT mx FROM mx),7) THEN 1 ELSE 0 END) AS unfilled_shifts FROM ramsay_health.ops.vwah_hoursassignment"
      ]
    },
    {
      "name": "workforce_hours_grade",
      "displayName": "Hours by Grade",
      "queryLines": [
        "WITH mx AS (SELECT MAX(CAST(CAST(ValidDate AS TIMESTAMP) AS DATE)) AS mx FROM ramsay_health.ops.vwah_hoursassignment) SELECT PersonGradeTypeName AS grade, ROUND(SUM(CAST(WorkHours AS DOUBLE)), 0) AS total_hours FROM ramsay_health.ops.vwah_hoursassignment WHERE CAST(CAST(ValidDate AS TIMESTAMP) AS DATE) >= date_sub((SELECT mx FROM mx), 7) GROUP BY PersonGradeTypeName ORDER BY total_hours DESC"
      ]
    },
    {
      "name": "workforce_fill_by_site",
      "displayName": "Fill Rate by Site",
      "queryLines": [
        "WITH mx AS (SELECT MAX(CAST(CAST(ValidDate AS TIMESTAMP) AS DATE)) AS mx FROM ramsay_health.ops.vwah_hoursassignment) SELECT SiteID,   ROUND(100.0 * SUM(CASE WHEN FulfillmentStatusName='Filled' THEN 1 ELSE 0 END) / COUNT(1), 1) AS fill_rate FROM ramsay_health.ops.vwah_hoursassignment WHERE CAST(CAST(ValidDate AS TIMESTAMP) AS DATE) >= date_sub((SELECT mx FROM mx), 7) GROUP BY SiteID"
      ]
    },
    {
      "name": "workforce_absence",
      "displayName": "Sickness/Absence by Reason",
      "queryLines": [
        "WITH mx AS (SELECT MAX(CAST(CAST(ValidDate AS TIMESTAMP) AS DATE)) AS mx FROM ramsay_health.ops.vwah_unavailability) SELECT UnavailabilityReasonGroup AS reason,   ROUND(SUM(COALESCE(WORKMINUTESMISSED, 0)) / 60.0, 0) AS hours_missed FROM ramsay_health.ops.vwah_unavailability WHERE CAST(CAST(ValidDate AS TIMESTAMP) AS DATE) >= date_sub((SELECT mx FROM mx), 7) GROUP BY UnavailabilityReasonGroup ORDER BY hours_missed DESC"
      ]
    },
    {
      "name": "patient_activity_kpis",
      "displayName": "Patient Activity KPIs",
      "queryLines": [
        "WITH mx AS (SELECT MAX(CAST(ReferralRaisedDate AS DATE)) AS mx FROM ramsay_health.ops.tbreferrals) SELECT   COUNT(DISTINCT PatientKey) AS patients,   COUNT(DISTINCT ReferralID) AS referrals,   COUNT(DISTINCT CASE WHEN HasAdmission=1 THEN ReferralID END) AS admissions,   ROUND(AVG(CAST(AgeAtDateOfReferral AS DOUBLE)), 1) AS avg_age FROM ramsay_health.ops.tbreferrals WHERE CAST(ReferralRaisedDate AS DATE) >= date_sub((SELECT mx FROM mx), 7)"
      ]
    },
    {
      "name": "patient_by_payor",
      "displayName": "Referrals by Payor",
      "queryLines": [
        "WITH mx AS (SELECT MAX(CAST(ReferralRaisedDate AS DATE)) AS mx FROM ramsay_health.ops.tbreferrals) SELECT PayorType, COUNT(DISTINCT ReferralID) AS referral_count FROM ramsay_health.ops.tbreferrals WHERE CAST(ReferralRaisedDate AS DATE) >= date_sub((SELECT mx FROM mx), 7) GROUP BY PayorType ORDER BY referral_count DESC"
      ]
    },
    {
      "name": "top_procedures",
      "displayName": "Top 3 Procedures",
      "queryLines": [
        "WITH mx AS (SELECT MAX(CAST(InvoiceCreatedDate AS DATE)) AS mx FROM (SELECT CAST(TO_DATE(InvoiceCreatedDate, 'yyyyMMdd') AS DATE) AS InvoiceCreatedDate FROM ramsay_health.ops.tbinvoice)) SELECT ProcedureGroup,   COUNT(*) AS procedure_count,   ROUND(SUM(CAST(InvoiceValue AS DOUBLE)), 0) AS total_revenue FROM ramsay_health.ops.tbinvoice WHERE ProcedureGroup <> 'null' AND ProcedureGroup IS NOT NULL   AND CAST(TO_DATE(InvoiceCreatedDate, 'yyyyMMdd') AS DATE) >= date_sub((SELECT mx FROM mx), 7) GROUP BY ProcedureGroup ORDER BY procedure_count DESC LIMIT 3"
      ]
    },
    {
      "name": "referrals_by_service",
      "displayName": "Referrals by Service",
      "queryLines": [
        "WITH mx AS (SELECT MAX(CAST(ReferralRaisedDate AS DATE)) AS mx FROM ramsay_health.ops.tbreferrals) SELECT ServiceName, COUNT(DISTINCT ReferralID) AS referral_count FROM ramsay_health.ops.tbreferrals WHERE CAST(ReferralRaisedDate AS DATE) >= date_sub((SELECT mx FROM mx), 7) GROUP BY ServiceName ORDER BY referral_count DESC"
      ]
    },
    {
      "name": "rtt_wait_bands",
      "displayName": "RTT Wait Band Distribution",
      "queryLines": [
        "WITH mx AS (SELECT MAX(CAST(TCIDate AS DATE)) AS mx FROM ramsay_health.ops.tbwlmds WHERE TCIDate <> '-') SELECT   CASE WHEN CAST(WeeksWaiting AS INT) <= 18 THEN 'Within 18wk'        WHEN CAST(WeeksWaiting AS INT) <= 26 THEN '18-26wk'        WHEN CAST(WeeksWaiting AS INT) <= 52 THEN '26-52wk' ELSE '52wk+' END AS WaitBand,   COUNT(*) AS patient_count FROM ramsay_health.ops.tbwlmds WHERE CAST(TCIDate AS DATE) >= date_sub((SELECT mx FROM mx), 7) GROUP BY WaitBand"
      ]
    },
    {
      "name": "rtt_breach_pct",
      "displayName": "RTT Breach %",
      "queryLines": [
        "WITH mx AS (SELECT MAX(CAST(TCIDate AS DATE)) AS mx FROM ramsay_health.ops.tbwlmds WHERE TCIDate <> '-') SELECT   ROUND(100.0 * SUM(CASE WHEN CAST(WeeksWaiting AS INT) > 18 THEN 1 ELSE 0 END) / COUNT(*), 1) AS breach_pct FROM ramsay_health.ops.tbwlmds WHERE CAST(TCIDate AS DATE) >= date_sub((SELECT mx FROM mx), 7)"
      ]
    },
    {
      "name": "theatre_cases",
      "displayName": "Theatre Cases by Site",
      "queryLines": [
        "WITH mx AS (SELECT MAX(CAST(SessionDate AS DATE)) AS mx FROM ramsay_health.ops.vw_theatre_throughput) SELECT SiteName, SUM(CAST(CasesCompleted AS INT)) AS cases_completed FROM ramsay_health.ops.vw_theatre_throughput WHERE SessionDate >= date_sub((SELECT mx FROM mx), 7) GROUP BY SiteName ORDER BY cases_completed DESC"
      ]
    },
    {
      "name": "diagnostic_util",
      "displayName": "Diagnostic Utilisation",
      "queryLines": [
        "WITH mx AS (SELECT MAX(CAST(SlotDate AS DATE)) AS mx FROM ramsay_health.ops.vw_diagnostic_capacity) SELECT Modality, ROUND(AVG(CAST(UtilisationPct AS DOUBLE)), 1) AS avg_util_pct FROM ramsay_health.ops.vw_diagnostic_capacity WHERE SlotDate >= date_sub((SELECT mx FROM mx), 7) GROUP BY Modality ORDER BY avg_util_pct DESC"
      ]
    },
    {
      "name": "readmission_rate",
      "displayName": "Readmission Rate",
      "queryLines": [
        "WITH rd AS (SELECT PatientKey, ReferralID, ServiceName,   CAST(ReferralRaisedDate AS DATE) AS raised,   LAG(CAST(ReferralRaisedDate AS DATE)) OVER (PARTITION BY PatientKey ORDER BY CAST(ReferralRaisedDate AS DATE)) AS prev_raised FROM ramsay_health.ops.tbreferrals), mx AS (SELECT MAX(raised) AS mx FROM rd) SELECT ROUND(100.0 * SUM(CASE WHEN prev_raised IS NOT NULL AND DATEDIFF(raised, prev_raised) <= 30 THEN 1 ELSE 0 END) / COUNT(*), 1) AS readmission_rate_pct FROM rd, mx WHERE raised >= date_sub(mx.mx, 7)"
      ]
    },
    {
      "name": "longest_waiting",
      "displayName": "Longest Waiting Services",
      "queryLines": [
        "WITH mx AS (SELECT MAX(CAST(TCIDate AS DATE)) AS mx FROM ramsay_health.ops.tbwlmds WHERE TCIDate <> '-') SELECT ServiceName, ROUND(AVG(CAST(WeeksWaiting AS DOUBLE)), 1) AS avg_weeks_waiting, COUNT(*) AS waiting_count FROM ramsay_health.ops.tbwlmds WHERE CAST(TCIDate AS DATE) >= date_sub((SELECT mx FROM mx), 7) GROUP BY ServiceName ORDER BY avg_weeks_waiting DESC LIMIT 5"
      ]
    },
    {
      "name": "bed_kpis",
      "displayName": "Bed Capacity KPIs",
      "queryLines": [
        "WITH mx AS (SELECT MAX(CAST(BedDate AS DATE)) AS mx FROM ramsay_health.ops.vw_bed_occupancy) SELECT   SUM(BedsAvailable) AS beds_available,   SUM(BedsOccupied) AS beds_occupied,   ROUND(AVG(OccupancyPct), 1) AS avg_occupancy_pct FROM ramsay_health.ops.vw_bed_occupancy WHERE BedDate >= date_sub((SELECT mx FROM mx), 7)"
