    },
    {
      "name": "theatre_util_site",
      "displayName": "Theatre Utilisation by Site",
      "queryLines": [
        "WITH mx AS (SELECT MAX(CAST(SessionDate AS DATE)) AS mx FROM ramsay_health.ops.vw_theatre_throughput) SELECT SiteName, ROUND(AVG(CAST(UtilisationPct AS DOUBLE)), 1) AS avg_util_pct FROM ramsay_health.ops.vw_theatre_throughput WHERE SessionDate >= date_sub((SELECT mx FROM mx), 7) GROUP BY SiteName ORDER BY avg_util_pct DESC"
