    },
    {
      "name": "bed_trend",
      "displayName": "Bed Occupancy Trend",
      "queryLines": [
        "WITH mx AS (SELECT MAX(CAST(BedDate AS DATE)) AS mx FROM ramsay_health.ops.vw_bed_occupancy) SELECT BedDate, SiteID, CAST(OccupancyPct AS DOUBLE) AS occupancy_pct FROM ramsay_health.ops.vw_bed_occupancy WHERE BedDate >= date_sub((SELECT mx FROM mx), 60) ORDER BY BedDate DESC"
