      "displayName": "Diagnostic Slots Capacity",
      "queryLines": [
        "WITH mx AS (SELECT MAX(CAST(SlotDate AS DATE)) AS mx FROM ramsay_health.ops.vw_diagnostic_capacity) SELECT Modality,   SUM(CAST(SlotsCapacity AS INT)) AS capacity,   SUM(CAST(SlotsBooked AS INT)) AS booked,   SUM(CAST(SlotsAvailable AS INT)) AS available FROM ramsay_health.ops.vw_diagnostic_capacity WHERE SlotDate >= date_sub((SELECT mx FROM mx), 7) GROUP BY Modality ORDER BY capacity DESC"
